async function loadDashboard() {
  try {
    let [users, posts, comments] = await Promise.all([
      fetch("/api/users").then(r => r.json()),
      fetch("/api/posts").then(r => r.json()),
      fetch("/api/comments").then(r => r.json())
    ]);

    console.log(users.length + " users");
    console.log(posts.length + " posts");
    console.log(comments.length + " comments");
  } catch (error) {
    console.error("One request failed:", error);
  }
}

// vs sequential (much slower!)
async function loadSequential() {
  let users = await fetch("/api/users").then(r => r.json());  // wait
  let posts = await fetch("/api/posts").then(r => r.json());  // wait
  let comments = await fetch("/api/comments").then(r => r.json());  // wait
}

async function loadMultipleSources() {
  let results = await Promise.allSettled([
    fetch("/api/users").then(r => r.json()),
    fetch("/api/bad-url").then(r => r.json()),  // will fail!
    fetch("/api/posts").then(r => r.json())
  ]);

  results.forEach((result, i) => {
    if (result.status === "fulfilled") {
      console.log(`Source ${i}: success`, result.value);
    } else {
      console.log(`Source ${i}: failed`, result.reason.message);
    }
  });
}
// Output:
// Source 0: success [...]
// Source 1: failed Not Found
// Source 2: success [...]

// Race — first to finish wins (or fails)
let result = await Promise.race([
  fetch("/api/fast"),
  fetch("/api/slow")
]);
console.log("Fastest response:", result.status);

// Timeout pattern
function fetchWithTimeout(url, ms) {
  let fetchPromise = fetch(url);
  let timeoutPromise = new Promise((_, reject) => {
    setTimeout(() => reject(new Error("Timeout!")), ms);
  });
  return Promise.race([fetchPromise, timeoutPromise]);
}

// Any — first success wins
let data = await Promise.any([
  fetch("/api/mirror1").then(r => r.json()),
  fetch("/api/mirror2").then(r => r.json()),
  fetch("/api/mirror3").then(r => r.json())
]);
console.log(data);  // first successful response
